package cli

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
)

// NewAuthenticatedAPIClient creates an API client targeting api.BaseURL()
// (the data API origin) carrying a token valid for that audience, minted by
// exchanging the matching login context's JWT at its own core (see
// auth.ResolveDataAPIToken).
//
// Pass insecureHTTP=true to allow plain HTTP base URLs for local
// development. Only the data origin is checked here — the bearer travels
// there on resource requests; the exchange leg is guarded by the
// per-context token manager (https required outside loopback/opt-in).
func NewAuthenticatedAPIClient(ctx context.Context, insecureHTTP bool) (*api.Client, error) {
	dataURL := api.BaseURL()
	if insecureHTTP {
		auth.EnableInsecureHTTP()
	} else if err := api.RequireSecureURL(dataURL); err != nil {
		return nil, fmt.Errorf("base URL check: %w", err)
	}

	// ResolveDataAPIToken discovers which login context the data host trusts
	// (via its /.well-known/entire-api.json) and exchanges that context's
	// token for the advertised audience. It normalises dataURL to an origin
	// internally.
	token, err := auth.ResolveDataAPIToken(ctx, dataURL)
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			// Wrap the original err (not the sentinel) so any context
			// the tokenmanager attached — keyring backend message,
			// expired-token reason — survives to the caller. The
			// errors.Is(err, auth.ErrNotLoggedIn) chain is preserved
			// because err already wraps the sentinel; replacing it
			// with the bare sentinel would drop that context for
			// zero behavioural gain.
			return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
		}
		return nil, fmt.Errorf("resolve API token: %w", err)
	}

	return api.NewClient(token), nil
}

// NewAuthenticatedEntireAPICellClient creates an API client for repo-scoped
// entire-api routes (e.g. experts). It exchanges the login JWT for a
// jurisdictional identity token and dials the entire-api cell directly, because
// the BFF does not proxy these routes for bearer callers (COR-666).
//
// fullName (owner/repo) and/or ulid identify the repo whose cell to reach. When
// either is supplied, the repo's OWNING cell + jurisdiction are resolved from
// the control plane (mirroring the BFF's per-repo cell selection) so the call
// lands in the region that hosts the repo. Resolution is best-effort: any
// failure yields a nil target and NewEntireAPICellClient falls back to
// home-jurisdiction routing, so the common same-region case never regresses.
func NewAuthenticatedEntireAPICellClient(ctx context.Context, insecureHTTP bool, fullName, ulid string) (*api.Client, error) {
	target := resolveRepoCellTarget(ctx, fullName, ulid)
	// NewEntireAPICellClient already returns user-facing, context-rich errors
	// (login hint, discovery-unavailable, region guidance); re-wrapping here
	// would bury them, so surface them verbatim.
	return auth.NewEntireAPICellClient(ctx, insecureHTTP, target) //nolint:wrapcheck // pass through contextual auth errors
}

type trailBackend string

const (
	trailBackendEnvVar    = "ENTIRE_TRAILS_BACKEND"
	trailBackendLegacy    = trailBackend("legacy")
	trailBackendEntireAPI = trailBackend("entire-api")
)

func configuredTrailBackend() (trailBackend, error) {
	switch value := strings.ToLower(strings.TrimSpace(os.Getenv(trailBackendEnvVar))); value {
	case "", string(trailBackendLegacy), "bff":
		return trailBackendLegacy, nil
	case string(trailBackendEntireAPI), "native":
		return trailBackendEntireAPI, nil
	default:
		return "", fmt.Errorf("invalid %s value %q: expected legacy or entire-api", trailBackendEnvVar, value)
	}
}

func isEntireAPITrailClient(client *api.Client) bool {
	return client != nil && client.TrailBackend() == string(trailBackendEntireAPI)
}

// newTrailAPIClient selects the legacy BFF by default. Setting
// ENTIRE_TRAILS_BACKEND=entire-api opts into direct, owning-cell routing.
var newTrailAPIClient = func(ctx context.Context, insecureHTTP bool, fullName string) (*api.Client, error) {
	backend, err := configuredTrailBackend()
	if err != nil {
		return nil, err
	}
	if backend == trailBackendLegacy {
		client, err := NewAuthenticatedAPIClient(ctx, insecureHTTP)
		if err != nil {
			return nil, err
		}
		return client.WithTrailBackend(string(backend)), nil
	}

	client, err := NewAuthenticatedEntireAPICellClient(ctx, insecureHTTP, fullName, "")
	if errors.Is(err, clusterdiscovery.ErrNoAuthContext) {
		return nil, fmt.Errorf("%w: %w", auth.ErrNotLoggedIn, err)
	}
	if err != nil {
		return nil, err
	}
	return client.WithTrailBackend(string(backend)), nil
}

package api

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
)

const (
	maxResponseBytes = 16 << 20
)

// Client is an authenticated HTTP client for the Entire API.
// It attaches the bearer token to all outgoing requests via the Authorization header.
type Client struct {
	httpClient *http.Client
	baseURL    string

	// trailBackend is "legacy" for the BFF or "entire-api" for the cell API.
	// Empty keeps the generic client's historical behavior and is treated as
	// legacy by CLI selection code only.
	trailBackend string
	trailRoutes  map[string]string

	// authSessionsPath is the base path for entire-core's login-session
	// endpoints (list / revoke / current). Set via WithAuthSessionsPath when the
	// client targets the auth host; empty otherwise, and the session methods
	// error out if called against an empty path.
	authSessionsPath string
}

// WithAuthSessionsPath sets the base path used by ListAuthSessions,
// RevokeCurrentAuthSession, and RevokeAuthSession. Returns the receiver for chaining
// at construction:
//
//	c := api.NewClientWithBaseURL(token, base).WithAuthSessionsPath(p)
func (c *Client) WithAuthSessionsPath(path string) *Client {
	c.authSessionsPath = path
	return c
}

// NewClient creates a new authenticated API client with an explicit bearer
// token, targeting the data API base URL (BaseURL()).
func NewClient(token string) *Client {
	return NewClientWithBaseURL(token, BaseURL())
}

// NewClientWithBaseURL creates a new authenticated API client targeting an
// explicit base URL. Use this for endpoints that live on a login server
// rather than the data API (e.g. auth-session management).
func NewClientWithBaseURL(token, baseURL string) *Client {
	return &Client{
		httpClient: &http.Client{
			Transport: &bearerTransport{
				token: token,
				base:  http.DefaultTransport,
			},
			// A cross-host redirect must never carry the Entire bearer to
			// another origin; refuse it rather than follow it. Same-origin
			// requests are guaranteed by the base-host check in do().
			CheckRedirect: rejectCrossHostRedirect,
		},
		baseURL: baseURL,
	}
}

// rejectCrossHostRedirect stops a redirect chain from leaving the origin the
// client was built for. Same-host redirects (e.g. a trailing-slash normalize)
// still follow, up to Go's usual 10-hop cap.
func rejectCrossHostRedirect(req *http.Request, via []*http.Request) error {
	if len(via) >= 10 {
		return errors.New("stopped after 10 redirects")
	}
	if len(via) > 0 && !strings.EqualFold(req.URL.Host, via[0].URL.Host) {
		return fmt.Errorf("refusing redirect to a different host (%s → %s): the Entire bearer must not leave its origin", via[0].URL.Host, req.URL.Host)
	}
	return nil
}

// requireSameHost rejects an endpoint whose host differs from the base URL's.
// It guards the direct case (a path that resolved to another host); redirects
// are handled by rejectCrossHostRedirect.
func requireSameHost(baseURL, endpoint string) error {
	b, err := url.Parse(baseURL)
	if err != nil {
		return fmt.Errorf("parse base URL: %w", err)
	}
	e, err := url.Parse(endpoint)
	if err != nil {
		return fmt.Errorf("parse endpoint URL: %w", err)
	}
	if !strings.EqualFold(b.Host, e.Host) {
		return fmt.Errorf("refusing to send an authenticated request to %q, which is not the API host %q", e.Host, b.Host)
	}
	return nil
}

// bearerTransport is an http.RoundTripper that injects the Authorization header.
//
// The token is only ever sent to the client's base host: do() rejects a request
// URL whose host differs from the base, and CheckRedirect refuses a cross-host
// redirect, so every request this transport sees is same-origin as the base.
//
// When token is empty, the Authorization header is omitted (rather than sent
// as a malformed "Authorization: Bearer "). This supports endpoints like
// recap that deliberately want the unauthenticated request to reach the
// server so it can return a typed 401 — callers that want a local fast-fail
// for missing auth should check ErrNotLoggedIn at construction time, not
// rely on the transport.
type bearerTransport struct {
	token string
	base  http.RoundTripper
}

func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	// Clone the request to avoid mutating the caller's request.
	r := req.Clone(req.Context())
	if t.token != "" {
		r.Header.Set("Authorization", "Bearer "+t.token)
	}
	r.Header.Set("User-Agent", versioninfo.UserAgent())
	if r.Header.Get("Accept") == "" {
		r.Header.Set("Accept", "application/json")
	}
	resp, err := t.base.RoundTrip(r)
	if err != nil {
		return nil, fmt.Errorf("round trip: %w", err)
	}
	return resp, nil
}

// Get sends an authenticated GET request to the given API-relative path.
func (c *Client) Get(ctx context.Context, path string) (*http.Response, error) {
	return c.do(ctx, http.MethodGet, path, nil, nil)
}

// GetStream sends an authenticated GET request with optional extra request
// headers (e.g. Accept: text/event-stream, Last-Event-ID) and returns the
// response with the body still open. Callers are responsible for reading and
// closing resp.Body. Intended for streaming endpoints such as Server-Sent
// Events; for normal JSON requests use Get.
func (c *Client) GetStream(ctx context.Context, path string, headers http.Header) (*http.Response, error) {
	return c.do(ctx, http.MethodGet, path, nil, headers)
}

// doJSON sends an authenticated request with an optional JSON-marshaled body.
func (c *Client) doJSON(ctx context.Context, method, path string, body any) (*http.Response, error) {
	var reader io.Reader
	if body != nil {
		if c.trailBackend == "legacy" {
			var err error
			body, err = legacyTrailRequestBody(body)
			if err != nil {
				return nil, err
			}
		}
		data, err := json.Marshal(body)
		if err != nil {
			return nil, fmt.Errorf("marshal request body: %w", err)
		}
		reader = bytes.NewReader(data)
	}
	return c.do(ctx, method, path, reader, nil)
}

// Post sends an authenticated POST request with a JSON body to the given API-relative path.
func (c *Client) Post(ctx context.Context, path string, body any) (*http.Response, error) {
	return c.doJSON(ctx, http.MethodPost, path, body)
}

// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
	return c.doJSON(ctx, http.MethodPut, path, body)
}

// Patch sends an authenticated PATCH request with a JSON body to the given API-relative path.
func (c *Client) Patch(ctx context.Context, path string, body any) (*http.Response, error) {
	return c.doJSON(ctx, http.MethodPatch, path, body)
}

// Delete sends an authenticated DELETE request to the given API-relative path.
func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
	return c.do(ctx, http.MethodDelete, path, nil, nil)
}

// Request sends an authenticated request with an explicit method, optional
// extra headers, and an optional raw body. It's the general-purpose escape
// hatch behind `entire api`; prefer the typed verbs (Get/Post/…) for normal
// use. The bearer, User-Agent, and default Accept are still attached by the
// transport; a body defaults to Content-Type: application/json unless the
// caller supplies its own via headers.
func (c *Client) Request(ctx context.Context, method, path string, headers http.Header, body io.Reader) (*http.Response, error) {
	return c.do(ctx, method, path, body, headers)
}

// WithTrailBackend marks a client as targeting one of the trail backends.
func (c *Client) WithTrailBackend(backend string) *Client {
	c.trailBackend = backend
	return c
}

// TrailBackend returns the backend marker set by WithTrailBackend.
func (c *Client) TrailBackend() string { return c.trailBackend }

// SetTrailRoute registers the entire-api base path for a resolved trail. The
// legacy BFF already uses trail-ID routes, so registration is a no-op there.
func (c *Client) SetTrailRoute(trailID, path string) {
	if c.trailBackend != "entire-api" {
		return
	}
	trailID = strings.TrimSpace(trailID)
	path = strings.TrimRight(strings.TrimSpace(path), "/")
	if trailID == "" || path == "" {
		return
	}
	if c.trailRoutes == nil {
		c.trailRoutes = make(map[string]string)
	}
	c.trailRoutes[url.PathEscape(trailID)] = path
}

func (c *Client) rewriteTrailRoute(path string) string {
	const prefix = "/api/v1/trails/"
	if !strings.HasPrefix(path, prefix) || len(c.trailRoutes) == 0 {
		return path
	}
	rest := strings.TrimPrefix(path, prefix)
	id, suffix, _ := strings.Cut(rest, "/")
	base, ok := c.trailRoutes[id]
	if !ok {
		return path
	}
	if suffix == "" {
		return base
	}
	return base + "/" + suffix
}

func (c *Client) do(ctx context.Context, method, path string, body io.Reader, headers http.Header) (*http.Response, error) {
	path = c.rewriteTrailRoute(path)
	endpoint, err := ResolveURLFromBase(c.baseURL, path)
	if err != nil {
		return nil, fmt.Errorf("resolve URL %s: %w", path, err)
	}
	// The bearer is only ever sent to the API's own host. A path that resolves
	// to another host (absolute or scheme-relative URL) would otherwise redirect
	// the Authorization header off-origin.
	if err := requireSameHost(c.baseURL, endpoint); err != nil {
		return nil, err
	}

	req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
	if err != nil {
		return nil, fmt.Errorf("create request: %w", err)
	}

	for k, vs := range headers {
		for _, v := range vs {
			req.Header.Add(k, v)
		}
	}

	// Default a body's Content-Type to JSON, but don't clobber a caller-supplied
	// one — the `entire api -H 'Content-Type: …'` escape hatch must be able to
	// send non-JSON bodies.
	if body != nil && req.Header.Get("Content-Type") == "" {
		req.Header.Set("Content-Type", "application/json")
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("%s %s: %w", method, path, err)
	}
	return resp, nil
}

// DecodeJSON reads the response body and decodes it into dest.
// It limits the body size to protect against unbounded reads.
// The caller is responsible for closing resp.Body.
func DecodeJSON(resp *http.Response, dest any) error {
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
	if err != nil {
		return fmt.Errorf("read response body: %w", err)
	}

	if err := json.Unmarshal(body, dest); err != nil {
		return fmt.Errorf("decode JSON response: %w", err)
	}

	return nil
}

// ErrorResponse represents a standard API error response. Older endpoints
// return {"error":"message"}; newer endpoints return
// {"error":{"code":"...","message":"...",...}}.
type ErrorResponse struct {
	Error any `json:"error"`
}

// Message extracts the human-readable error message from either envelope shape.
func (e ErrorResponse) Message() string {
	switch v := e.Error.(type) {
	case string:
		return strings.TrimSpace(v)
	case map[string]any:
		if message, ok := v["message"].(string); ok && strings.TrimSpace(message) != "" {
			return strings.TrimSpace(message)
		}
		if code, ok := v["code"].(string); ok && strings.TrimSpace(code) != "" {
			return strings.TrimSpace(code)
		}
	}
	return ""
}

// HTTPError is returned by CheckResponse for non-2xx responses. Callers can use
// errors.As to inspect the HTTP status, or IsHTTPErrorStatus for a quick check.
type HTTPError struct {
	StatusCode int
	Message    string
}

func (e *HTTPError) Error() string {
	if e.Message != "" {
		return fmt.Sprintf("API error: %s (status %d)", e.Message, e.StatusCode)
	}
	return fmt.Sprintf("API error: status %d", e.StatusCode)
}

// IsHTTPErrorStatus reports whether err wraps an *HTTPError with the given HTTP status.
func IsHTTPErrorStatus(err error, status int) bool {
	var ae *HTTPError
	return errors.As(err, &ae) && ae.StatusCode == status
}

// CheckResponse returns an error if the response status code indicates failure.
// For non-2xx responses, it reads and parses the error message from the body
// and returns it as an *HTTPError. The caller is responsible for closing resp.Body.
func CheckResponse(resp *http.Response) error {
	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		return nil
	}

	apiError := &HTTPError{StatusCode: resp.StatusCode}

	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
	if err != nil {
		return apiError
	}

	var parsed ErrorResponse
	if err := json.Unmarshal(body, &parsed); err == nil {
		if message := parsed.Message(); message != "" {
			apiError.Message = message
			return apiError
		}
	}

	if text := strings.TrimSpace(string(body)); text != "" {
		apiError.Message = text
	}
	return apiError
}

package api

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
)

// TrailsEnabled probes trail availability: 2xx=true, 403/404/410=false,
// everything else ambiguous.
func (c *Client) TrailsEnabled(ctx context.Context, forge, owner, repo string) (bool, error) {
	query := "limit=1"
	if c.TrailBackend() == "entire-api" {
		query = "pageSize=1"
	}
	resp, err := c.Get(ctx, fmt.Sprintf("/api/v1/trails/%s/%s/%s?%s",
		url.PathEscape(forge), url.PathEscape(owner), url.PathEscape(repo), query))
	if err != nil {
		return false, fmt.Errorf("probe trails enablement: %w", err)
	}
	defer resp.Body.Close()
	// Drain (bounded) so net/http can reuse the connection; the body is unused.
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<16)) //nolint:errcheck // best-effort drain
	if resp.StatusCode >= http.StatusOK && resp.StatusCode < http.StatusMultipleChoices {
		return true, nil
	}
	switch resp.StatusCode {
	case http.StatusForbidden, http.StatusNotFound, http.StatusGone:
		return false, nil
	default:
		return false, fmt.Errorf("probe trails enablement: unexpected status %s", resp.Status)
	}
}

package api

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
	"unicode"
)

var rawJSONType = reflect.TypeFor[json.RawMessage]()

// normalizeLegacyTrailJSON accepts the former BFF's snake_case trail payloads
// while the CLI moves to entire-api's camelCase contract. Normalization follows
// the destination schema so map, interface, RawMessage, and unknown fields keep
// their user-defined keys unchanged.
func normalizeLegacyTrailJSON(data []byte, dest any) ([]byte, error) {
	var value any
	if err := json.Unmarshal(data, &value); err != nil {
		return nil, fmt.Errorf("decode trail JSON: %w", err)
	}
	normalized, err := json.Marshal(normalizeTrailJSONValue(value, reflect.TypeOf(dest)))
	if err != nil {
		return nil, fmt.Errorf("encode normalized trail JSON: %w", err)
	}
	return normalized, nil
}

func decodeNormalizedTrailJSON(data []byte, dest any) error {
	normalized, err := normalizeLegacyTrailJSON(data, dest)
	if err != nil {
		return err
	}
	if err := json.Unmarshal(normalized, dest); err != nil {
		return fmt.Errorf("decode normalized trail JSON: %w", err)
	}
	return nil
}

func legacyTrailRequestBody(body any) (any, error) {
	data, err := json.Marshal(body)
	if err != nil {
		return nil, fmt.Errorf("marshal trail request: %w", err)
	}
	var value any
	if err := json.Unmarshal(data, &value); err != nil {
		return nil, fmt.Errorf("decode trail request: %w", err)
	}
	return snakeCaseTrailJSONValue(value, reflect.TypeOf(body)), nil
}

func snakeCaseTrailJSONValue(value any, typ reflect.Type) any {
	typ = indirectTrailJSONType(typ)
	if typ == nil || typ == rawJSONType {
		return value
	}
	switch v := value.(type) {
	case map[string]any:
		if typ.Kind() != reflect.Struct {
			return value
		}
		out := make(map[string]any, len(v))
		for key, child := range v {
			fieldType, canonical, ok := trailJSONStructField(typ, key)
			if !ok {
				out[key] = child
				continue
			}
			out[lowerCamelToSnake(canonical)] = snakeCaseTrailJSONValue(child, fieldType)
		}
		return out
	case []any:
		if typ.Kind() != reflect.Slice && typ.Kind() != reflect.Array {
			return value
		}
		for i := range v {
			v[i] = snakeCaseTrailJSONValue(v[i], typ.Elem())
		}
	}
	return value
}

func lowerCamelToSnake(value string) string {
	var out strings.Builder
	for i, r := range value {
		if unicode.IsUpper(r) {
			if i > 0 {
				out.WriteByte('_')
			}
			r = unicode.ToLower(r)
		}
		out.WriteRune(r)
	}
	return out.String()
}

func normalizeTrailJSONValue(value any, typ reflect.Type) any {
	typ = indirectTrailJSONType(typ)
	if typ == nil || typ == rawJSONType {
		return value
	}
	switch v := value.(type) {
	case map[string]any:
		if typ.Kind() != reflect.Struct {
			return value
		}
		out := make(map[string]any, len(v))
		for key, child := range v {
			fieldType, canonical, ok := trailJSONStructField(typ, NormalizeTrailJSONKey(key))
			if !ok {
				// Unknown fields are ignored by encoding/json. Preserve their entire
				// subtree so a future free-form field cannot be silently re-cased.
				out[key] = child
				continue
			}
			out[canonical] = normalizeTrailJSONValue(child, fieldType)
		}
		return out
	case []any:
		if typ.Kind() != reflect.Slice && typ.Kind() != reflect.Array {
			return value
		}
		for i := range v {
			v[i] = normalizeTrailJSONValue(v[i], typ.Elem())
		}
	}
	return value
}

func indirectTrailJSONType(typ reflect.Type) reflect.Type {
	for typ != nil && typ.Kind() == reflect.Pointer {
		typ = typ.Elem()
	}
	return typ
}

func trailJSONStructField(typ reflect.Type, key string) (reflect.Type, string, bool) {
	for i := range typ.NumField() {
		field := typ.Field(i)
		name := strings.Split(field.Tag.Get("json"), ",")[0]
		if name == "" {
			name = field.Name
		}
		if name == "-" || name != key {
			continue
		}
		return field.Type, name, true
	}
	return nil, "", false
}

// NormalizeTrailJSONKey converts a legacy trail key to its canonical entire-api
// spelling. Event and response normalization share this helper so aliases do
// not diverge between SSE and regular JSON decoding.
func NormalizeTrailJSONKey(value string) string {
	camel := snakeToLowerCamel(value)
	if camel == "reviewSessionId" {
		return "reviewId"
	}
	return camel
}

func snakeToLowerCamel(value string) string {
	if !strings.ContainsRune(value, '_') {
		return value
	}
	var out strings.Builder
	upperNext := false
	for _, r := range value {
		if r == '_' {
			upperNext = true
			continue
		}
		if upperNext {
			r = unicode.ToUpper(r)
			upperNext = false
		}
		out.WriteRune(r)
	}
	return out.String()
}

package cli

import "testing"

func TestConfiguredTrailBackend(t *testing.T) {
	tests := []struct {
		name  string
		value string
		want  trailBackend
	}{
		{name: "default", want: trailBackendLegacy},
		{name: "legacy", value: "legacy", want: trailBackendLegacy},
		{name: "bff alias", value: "bff", want: trailBackendLegacy},
		{name: "entire-api", value: "entire-api", want: trailBackendEntireAPI},
		{name: "native alias", value: "native", want: trailBackendEntireAPI},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Setenv(trailBackendEnvVar, tt.value)
			got, err := configuredTrailBackend()
			if err != nil {
				t.Fatal(err)
			}
			if got != tt.want {
				t.Fatalf("backend = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestConfiguredTrailBackendRejectsUnknownValue(t *testing.T) {
	t.Setenv(trailBackendEnvVar, "something-else")
	if _, err := configuredTrailBackend(); err == nil {
		t.Fatal("expected invalid backend error")
	}
}

func TestTrailBackendScopedAPIBaseIncludesBackend(t *testing.T) {
	t.Setenv(trailBackendEnvVar, "legacy")
	legacy, err := trailBackendScopedAPIBase()
	if err != nil {
		t.Fatal(err)
	}
	t.Setenv(trailBackendEnvVar, "entire-api")
	native, err := trailBackendScopedAPIBase()
	if err != nil {
		t.Fatal(err)
	}
	if legacy == native {
		t.Fatalf("backend cache scopes must differ: %q", legacy)
	}
}

package cli

import (
	"fmt"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/spf13/cobra"
)

// newAuthUseCmd switches the active login context.
//
// The active context is the preferred identity for both `git clone entire://…`
// (it authenticates any cluster fronted by its login server) and the
// control-plane commands (auth status, org/project/repo/grant), which dial the
// context's core. Switching takes effect on the next operation; resolution
// recomputes every time. Activity/search/dispatch and legacy trail commands take
// their host from ENTIRE_API_BASE_URL; ENTIRE_TRAILS_BACKEND=entire-api routes
// trail commands to the repository's owning cell. All use the active identity.
func newAuthUseCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "use <context>",
		Short: "Switch the active login context",
		Long: "Switch the active login context.\n\n" +
			"The active context is the identity for every authenticated operation:\n" +
			"`git clone entire://…`, the control-plane commands (auth status,\n" +
			"org/project/repo/grant), and the data-API commands (activity, search,\n" +
			"trail, dispatch). The switch takes effect on the next operation.\n\n" +
			"This is persistent and machine-wide — it changes the identity for every\n" +
			"shell, worktree, and background git hook until you switch back. To act as\n" +
			"another login for a single command instead, pass --context, or set\n" +
			"ENTIRE_CONTEXT for one shell or one git operation:\n\n" +
			"  entire --context staging activity\n" +
			"  ENTIRE_CONTEXT=staging git push\n\n" +
			"Activity/search/dispatch and legacy trail commands take their host from\n" +
			"ENTIRE_API_BASE_URL. ENTIRE_TRAILS_BACKEND=entire-api routes trails to the\n" +
			"repository's owning cell. The selected context supplies the identity.",
		Args:              cobra.ExactArgs(1),
		ValidArgsFunction: completeContextNames,
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := auth.SetCurrentContext(args[0]); err != nil {
				return err //nolint:wrapcheck // already a user-facing message
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Now using context %q.\n", args[0])
			return nil
		},
	}
}

// completeContextNames is the ValidArgsFunction for commands taking a single
// <context> positional. It offers the stored context names, each annotated
// (shell-completion descriptions, after a tab) with handle, core URL, and an
// "(active)" marker for the current context. Errors are swallowed because
// completion runs on every TAB press; a failed read just yields no suggestions.
func completeContextNames(_ *cobra.Command, args []string, _ string) ([]string, cobra.ShellCompDirective) {
	if len(args) != 0 {
		// <context> is a single positional; nothing to complete past it.
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	all, current, err := auth.Contexts()
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	out := make([]string, 0, len(all))
	for _, c := range all {
		desc := c.Handle
		if c.CoreURL != "" {
			desc += " " + c.CoreURL
		}
		if c.Name == current {
			desc += " (active)"
		}
		out = append(out, c.Name+"\t"+desc)
	}
	return out, cobra.ShellCompDirectiveNoFileComp
}

// newAuthContextsCmd lists the stored login contexts and marks the active
// one. Purely local — it reads contexts.json, no network.
func newAuthContextsCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "contexts",
		Short: "List stored login contexts",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAuthContexts(cmd.OutOrStdout())
		},
	}
}

func runAuthContexts(w io.Writer) error {
	all, current, err := auth.Contexts()
	if err != nil {
		return err //nolint:wrapcheck // already a user-facing message
	}
	if len(all) == 0 {
		fmt.Fprintln(w, "No login contexts. Run 'entire login' to authenticate.")
		return nil
	}
	renderContextsTable(w, all, current)
	return nil
}

// renderContextsTable prints the saved login contexts as a styled, aligned
// table with column headers. The active context is flagged with "*" in the
// leading column. Purely local data — no network, no timestamps — so it
// reuses the auth-table styles but only the header/name/value/accent slots.
func renderContextsTable(w io.Writer, all []*contexts.Context, current string) {
	sty := newAuthTableStyles(w)

	header := []string{
		"", // active marker
		sty.render(sty.header, "CONTEXT"),
		sty.render(sty.header, "HANDLE"),
		sty.render(sty.header, "LOGIN SERVER"),
	}

	rows := make([][]string, 0, len(all))
	for _, c := range all {
		marker := " "
		name := sty.render(sty.value, c.Name)
		if c.Name == current {
			marker = sty.render(sty.id, "*")
			name = sty.render(sty.name, c.Name)
		}
		rows = append(rows, []string{
			marker,
			name,
			sty.render(sty.value, fallback(c.Handle, placeholderDash)),
			sty.render(sty.value, fallback(c.CoreURL, placeholderDash)),
		})
	}

	renderAlignedTable(w, header, rows)
}

package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/validation"

	"github.com/spf13/cobra"
)

const (
	trailEnablementCacheTTL                   = time.Hour
	agentHelpTrailsRefreshFailureBackoff      = 5 * time.Minute
	trailEnablementSessionStartRefreshTimeout = time.Second
	trailEnablementRefreshTimeout             = 3 * time.Second
)

type trailEnablementCacheStatus int

const (
	trailEnablementCacheUnknown trailEnablementCacheStatus = iota
	trailEnablementCacheEnabled
	trailEnablementCacheDisabled
)

type trailEnablementScope struct {
	Forge     string `json:"forge"`
	Owner     string `json:"owner"`
	Repo      string `json:"repo"`
	RepoKey   string `json:"repo_key"`
	APIBase   string `json:"api_base"`
	AuthKey   string `json:"auth_key"`
	Supported bool   `json:"supported"`
}

func cachedTrailsEnablementForScope(ctx context.Context, scope trailEnablementScope, now time.Time) trailEnablementCacheStatus {
	prefs, err := settings.LoadClonePreferences(ctx)
	if err != nil || prefs.TrailsEnabled == nil || prefs.TrailsEnabledCheckedAt == nil {
		return trailEnablementCacheUnknown
	}
	if !trailEnablementCacheMatchesScope(prefs, scope) || trailEnablementCacheExpired(*prefs.TrailsEnabledCheckedAt, now) {
		return trailEnablementCacheUnknown
	}
	if *prefs.TrailsEnabled {
		return trailEnablementCacheEnabled
	}
	return trailEnablementCacheDisabled
}

func trailEnablementCacheMatchesScope(prefs *settings.ClonePreferences, scope trailEnablementScope) bool {
	return prefs.TrailsEnabledRepoKey == scope.RepoKey &&
		prefs.TrailsEnabledAPIBase == scope.APIBase &&
		prefs.TrailsEnabledAuthKey == scope.AuthKey
}

func trailEnablementCacheExpired(checkedAt time.Time, now time.Time) bool {
	if checkedAt.IsZero() {
		return true
	}
	if now.Before(checkedAt) {
		return true
	}
	return now.Sub(checkedAt) > trailEnablementCacheTTL
}

func currentTrailEnablementScope(ctx context.Context) (trailEnablementScope, error) {
	rawURL, err := gitremote.GetRemoteURL(ctx, "origin")
	if err != nil {
		return trailEnablementScope{}, fmt.Errorf("get origin remote: %w", err)
	}
	if strings.TrimSpace(rawURL) == "" {
		return trailEnablementScope{}, errors.New("get origin remote: empty URL")
	}
	info, err := gitremote.ParseURL(rawURL)
	if err != nil {
		return trailEnablementScope{}, fmt.Errorf("parse origin remote: %w", err)
	}
	authKey, err := auth.LocalIdentityCacheKey()
	if err != nil {
		return trailEnablementScope{}, fmt.Errorf("resolve auth cache key: %w", err)
	}
	apiBase, err := trailBackendScopedAPIBase()
	if err != nil {
		return trailEnablementScope{}, err
	}
	return trailEnablementScope{
		Forge:     info.Forge,
		Owner:     info.Owner,
		Repo:      info.Repo,
		RepoKey:   trailEnablementRepoKey(info.Forge, info.Owner, info.Repo),
		APIBase:   apiBase,
		AuthKey:   authKey,
		Supported: info.Forge != "",
	}, nil
}

func trailEnablementRepoKey(forge, owner, repo string) string {
	return strings.Join([]string{forge, owner, repo}, "/")
}

func trailBackendScopedAPIBase() (string, error) {
	backend, err := configuredTrailBackend()
	if err != nil {
		return "", err
	}
	return string(backend) + ":" + api.BaseURL(), nil
}

func saveTrailEnablementScopeHint(ctx context.Context, sessionID string, scope trailEnablementScope) error {
	path, err := trailEnablementScopeHintPath(ctx, sessionID)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return fmt.Errorf("create session state dir: %w", err)
	}
	data, err := jsonutil.MarshalIndentWithNewline(scope, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal trail scope hint: %w", err)
	}
	if err := jsonutil.WriteFileAtomic(path, data, 0o600); err != nil {
		return fmt.Errorf("write trail scope hint: %w", err)
	}
	return nil
}

func loadTrailEnablementScopeHint(ctx context.Context, sessionID string) (trailEnablementScope, bool, error) {
	path, err := trailEnablementScopeHintPath(ctx, sessionID)
	if err != nil {
		return trailEnablementScope{}, false, err
	}
	data, err := os.ReadFile(path) //nolint:gosec // path is derived from validated session ID
	if err != nil {
		if os.IsNotExist(err) {
			return trailEnablementScope{}, false, nil
		}
		return trailEnablementScope{}, false, fmt.Errorf("read trail scope hint: %w", err)
	}
	var scope trailEnablementScope
	if err := json.Unmarshal(data, &scope); err != nil {
		return trailEnablementScope{}, false, fmt.Errorf("parse trail scope hint: %w", err)
	}
	return scope, true, nil
}

func trailEnablementScopeHintPath(ctx context.Context, sessionID string) (string, error) {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return "", fmt.Errorf("invalid session ID: %w", err)
	}
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}
	return filepath.Join(commonDir, session.SessionStateDirName, sessionID+".trail-scope.json"), nil
}

func saveTrailsEnabledForRepo(ctx context.Context, enabled bool) error {
	scope, err := currentTrailEnablementScope(ctx)
	if err != nil {
		return err
	}
	return saveTrailsEnabledForScope(ctx, scope, enabled, time.Now())
}

func saveTrailsEnabledForRemote(ctx context.Context, forge, owner, repo string, enabled bool) error {
	authKey, err := auth.LocalIdentityCacheKey()
	if err != nil {
		return fmt.Errorf("resolve auth cache key: %w", err)
	}
	apiBase, err := trailBackendScopedAPIBase()
	if err != nil {
		return err
	}
	scope := trailEnablementScope{
		Forge:     forge,
		Owner:     owner,
		Repo:      repo,
		RepoKey:   trailEnablementRepoKey(forge, owner, repo),
		APIBase:   apiBase,
		AuthKey:   authKey,
		Supported: forge != "",
	}
	return saveTrailsEnabledForScope(ctx, scope, enabled, time.Now())
}

func saveTrailsEnabledForScope(ctx context.Context, scope trailEnablementScope, enabled bool, checkedAt time.Time) error {
	enabledCopy := enabled
	checkedAtUTC := checkedAt.UTC()
	if err := settings.ModifyClonePreferences(ctx, func(prefs *settings.ClonePreferences) error {
		prefs.TrailsEnabled = &enabledCopy
		prefs.TrailsEnabledCheckedAt = &checkedAtUTC
		prefs.TrailsEnabledRepoKey = scope.RepoKey
		prefs.TrailsEnabledAPIBase = scope.APIBase
		prefs.TrailsEnabledAuthKey = scope.AuthKey
		return nil
	}); err != nil {
		return fmt.Errorf("save clone preferences: %w", err)
	}
	return nil
}

// recentAgentHelpTrailsRefreshFailure reports whether agent-help should back off
// after a failed availability refresh for this exact repo/API/auth scope. This
// marker is deliberately separate from TrailsEnabled: lifecycle SessionStart
// must still perform its authoritative probe and decide context injection.
func recentAgentHelpTrailsRefreshFailure(ctx context.Context, scope trailEnablementScope, now time.Time) bool {
	prefs, err := settings.LoadClonePreferences(ctx)
	if err != nil || prefs.TrailsAgentHelpRefreshFailedAt == nil {
		return false
	}
	if prefs.TrailsAgentHelpFailureRepoKey != scope.RepoKey ||
		prefs.TrailsAgentHelpFailureAPIBase != scope.APIBase ||
		prefs.TrailsAgentHelpFailureAuthKey != scope.AuthKey {
		return false
	}
	failedAt := *prefs.TrailsAgentHelpRefreshFailedAt
	if failedAt.IsZero() || now.Before(failedAt) {
		return false
	}
	return now.Sub(failedAt) <= agentHelpTrailsRefreshFailureBackoff
}

func saveAgentHelpTrailsRefreshFailure(ctx context.Context, scope trailEnablementScope, failedAt time.Time) error {
	failedAtUTC := failedAt.UTC()
	if err := settings.ModifyClonePreferences(ctx, func(prefs *settings.ClonePreferences) error {
		prefs.TrailsAgentHelpRefreshFailedAt = &failedAtUTC
		prefs.TrailsAgentHelpFailureRepoKey = scope.RepoKey
		prefs.TrailsAgentHelpFailureAPIBase = scope.APIBase
		prefs.TrailsAgentHelpFailureAuthKey = scope.AuthKey
		return nil
	}); err != nil {
		return fmt.Errorf("save clone preferences: %w", err)
	}
	return nil
}

// refreshTrailsEnabledCacheIfStaleForScope refreshes the trails-enablement
// cache when it's unknown/expired for scope. Callers on hot, latency-sensitive
// paths (SessionStart) must not block on this: resolving the API token and
// dialing TrailsEnabled can stall for seconds when the host is slow or
// unreachable (VPN, firewall, offline). Instead of doing that
// network work inline, hand it off to a detached `__refresh_trail_enablement`
// subprocess and return immediately; a later SessionStart will observe the
// freshly written cache once the subprocess completes. The "not supported"
// case is answered locally (no network) since it's free.
func refreshTrailsEnabledCacheIfStaleForScope(ctx context.Context, scope trailEnablementScope) error {
	if cachedTrailsEnablementForScope(ctx, scope, time.Now()) != trailEnablementCacheUnknown {
		return nil
	}
	if !scope.Supported {
		return saveTrailsEnabledForScope(ctx, scope, false, time.Now())
	}
	spawnDetachedTrailEnablementRefresh(ctx)
	return nil
}

// trailRefreshAPIClient is the authenticated-client seam used by
// runTrailEnablementRefresh, swapped in tests so they can force the
// refreshTrailsEnabledCacheForScope error branch (e.g. a broken API host)
// without a real login context. Production code always uses the repo-routed
// entire-api cell client.
var trailRefreshAPIClient = func(ctx context.Context, insecureHTTP bool, fullName string) (*api.Client, error) {
	return newTrailAPIClient(ctx, insecureHTTP, fullName)
}

// runTrailEnablementRefresh performs the actual (potentially slow) network
// refresh. It is invoked from the detached `__refresh_trail_enablement`
// subprocess spawned by refreshTrailsEnabledCacheIfStaleForScope, never
// synchronously from a hook path.
func runTrailEnablementRefresh(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, trailEnablementRefreshTimeout)
	defer cancel()

	// This runs detached with stdout/stderr discarded, so log at debug to the
	// repo's .entire/logs/entire.log (initialized by newRefreshTrailEnablementCmd).
	// Without this, an unreachable/failing host would leave the background
	// refresh silently failing with no diagnostic trail.
	logCtx := logging.WithComponent(ctx, "trail-refresh")

	scope, err := currentTrailEnablementScope(ctx)
	if err != nil {
		logging.Debug(logCtx, "trails enablement refresh skipped: scope unresolved", "error", err.Error())
		return nil
	}
	// Another process (e.g. a fast-following SessionStart, or a concurrent
	// refresh already in flight) may have populated the cache first.
	if cachedTrailsEnablementForScope(ctx, scope, time.Now()) != trailEnablementCacheUnknown {
		return nil
	}
	if !scope.Supported {
		if err := saveTrailsEnabledForScope(ctx, scope, false, time.Now()); err != nil {
			logging.Debug(logCtx, "trails enablement refresh failed to save unsupported scope", "error", err.Error())
		}
		return nil
	}
	client, err := trailRefreshAPIClient(ctx, false, scope.Owner+"/"+scope.Repo)
	if err != nil {
		logging.Debug(logCtx, "trails enablement refresh skipped: authenticated client unavailable", "error", err.Error())
		return nil
	}
	// Best-effort: this runs from the detached __refresh_trail_enablement
	// subprocess (stdout/stderr discarded, see newRefreshTrailEnablementCmd),
	// so a transient network/API failure here must not surface as a non-zero
	// process exit — there's no one watching it and no user-visible benefit,
	// only a spurious failure signal. The failure is still diagnosable via the
	// debug log above.
	if _, err := refreshTrailsEnabledCacheForScope(ctx, client, scope); err != nil {
		logging.Debug(logCtx, "trails enablement refresh failed", "error", err.Error())
		return nil
	}
	logging.Debug(logCtx, "trails enablement refresh completed", "enabled_repo_key", scope.RepoKey)
	return nil
}

// trailRefreshSpawn is the process-spawn seam used by
// spawnDetachedTrailEnablementRefresh. Swapped in tests so they can assert
// SessionStart never blocks on it without forking a real subprocess (a real
// `go test` binary doesn't understand `__refresh_trail_enablement` as an
// argument). Production code always uses spawnDetachedTrailRefreshProcess.
var trailRefreshSpawn = spawnDetachedTrailRefreshProcess

// spawnDetachedTrailRefreshProcess starts `entire __refresh_trail_enablement`
// as a detached child so the trails-enablement network refresh can't add
// latency to the SessionStart hook that spawned it. The child runs from the
// worktree root because the refresh resolves the origin remote and
// git-common-dir for cache storage from its working directory.
func spawnDetachedTrailRefreshProcess(worktreeRoot string) {
	execx.SpawnDetached(worktreeRoot, "__refresh_trail_enablement")
}

// trailRefreshSpawnThrottle bounds how often SessionStart forks a detached
// refresh child for a given repo. When the API host is unreachable the refresh
// never writes the cache, so cachedTrailsEnablementForScope stays unknown and
// the hourly TTL never starts — without this guard every SessionStart (and
// every concurrent worktree) would fork a fresh child that re-opens the repo,
// re-resolves auth, and re-dials the dead host. Tying the window to the child's
// own timeout collapses a burst of hooks to roughly one child per window while
// still retrying promptly once the host recovers.
const trailRefreshSpawnThrottle = trailEnablementRefreshTimeout

// spawnDetachedTrailEnablementRefresh starts a detached child process that
// runs runTrailEnablementRefresh in the background. Best-effort: if the
// worktree root can't be resolved or the subprocess can't be spawned, the
// cache simply stays unknown and the next SessionStart tries again. A recent
// spawn for the same repo short-circuits so a burst of hooks doesn't fork a
// herd of redundant refresh children (see trailRefreshRecentlySpawned).
func spawnDetachedTrailEnablementRefresh(ctx context.Context) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return
	}
	if commonDir, err := session.GetGitCommonDir(ctx); err == nil &&
		trailRefreshRecentlySpawned(commonDir, time.Now()) {
		return
	}
	trailRefreshSpawn(worktreeRoot)
}

// trailRefreshRecentlySpawned reports whether a detached refresh was spawned for
// this repo within trailRefreshSpawnThrottle and, when it wasn't, records now as
// the most recent spawn. The read-and-record is serialized with a flock keyed to
// the shared git-common-dir (so every worktree of the repo agrees), collapsing a
// burst of concurrent SessionStart hooks to a single child rather than one per
// hook. Best-effort: any error resolving, locking, or writing the marker falls
// through to spawning — never worse than before this guard existed.
func trailRefreshRecentlySpawned(commonDir string, now time.Time) bool {
	dir := filepath.Join(commonDir, "entire")
	// Create the directory before acquiring the lock: flock.Acquire opens the
	// lock file, which fails if its parent doesn't exist yet (mirrors
	// ModifyClonePreferences, which MkdirAlls before locking).
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return false
	}
	markerPath := filepath.Join(dir, "trail-refresh-spawn")
	release, err := flock.Acquire(markerPath + ".lock")
	if err != nil {
		return false
	}
	defer release()

	if data, readErr := os.ReadFile(markerPath); readErr == nil { //nolint:gosec // markerPath is derived from the trusted git-common-dir, not user input
		if last, parseErr := time.Parse(time.RFC3339Nano, strings.TrimSpace(string(data))); parseErr == nil &&
			now.After(last) && now.Sub(last) < trailRefreshSpawnThrottle {
			return true
		}
	}
	//nolint:errcheck // best-effort marker; a failed write just means the next hook re-spawns
	_ = os.WriteFile(markerPath, []byte(now.UTC().Format(time.RFC3339Nano)), 0o600)
	return false
}

// newRefreshTrailEnablementCmd creates the hidden command that performs the
// (potentially slow) trails-enablement network refresh out of band. It is
// invoked by spawnDetachedTrailEnablementRefresh from a detached subprocess
// and should not be called directly.
func newRefreshTrailEnablementCmd() *cobra.Command {
	return &cobra.Command{
		Use:    "__refresh_trail_enablement",
		Hidden: true,
		Args:   cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			// Detached child with discarded stdout/stderr: initialize file
			// logging so a failing background refresh (e.g. an unreachable
			// host) is diagnosable in .entire/logs/entire.log rather than
			// vanishing. Guard on WorktreeRoot first — matching resume/rewind/
			// reset/explain — so a child whose worktree was removed or relocated
			// between spawn and exec (or a manual invocation outside a repo)
			// doesn't create a stray .entire/logs/ in an arbitrary directory;
			// logging.Init falls back to cwd when WorktreeRoot fails.
			if _, err := paths.WorktreeRoot(ctx); err == nil {
				logging.SetLogLevelGetter(GetLogLevel)
				if err := logging.Init(ctx, ""); err == nil {
					defer logging.Close()
				}
			}
			return runTrailEnablementRefresh(ctx)
		},
	}
}

func refreshTrailsEnabledCache(ctx context.Context, client *api.Client) (bool, error) {
	scope, err := currentTrailEnablementScope(ctx)
	if err != nil {
		return false, err
	}
	return refreshTrailsEnabledCacheForScope(ctx, client, scope)
}

func refreshTrailsEnabledCacheForScope(ctx context.Context, client *api.Client, scope trailEnablementScope) (bool, error) {
	if !scope.Supported {
		if err := saveTrailsEnabledForScope(ctx, scope, false, time.Now()); err != nil {
			return false, err
		}
		return false, nil
	}
	enabled, err := client.TrailsEnabled(ctx, scope.Forge, scope.Owner, scope.Repo)
	if err != nil {
		return false, fmt.Errorf("check trails enablement: %w", err)
	}
	if err := saveTrailsEnabledForScope(ctx, scope, enabled, time.Now()); err != nil {
		return false, err
	}
	return enabled, nil
}

func saveTrailsEnabledForRepoBestEffort(ctx context.Context, enabled bool) {
	if err := saveTrailsEnabledForRepo(ctx, enabled); err != nil {
		logging.Debug(ctx, "failed to cache trails enablement", "error", err)
	}
}

func saveTrailsEnabledForRemoteBestEffort(ctx context.Context, forge, owner, repo string, enabled bool) {
	if err := saveTrailsEnabledForRemote(ctx, forge, owner, repo, enabled); err != nil {
		logging.Debug(ctx, "failed to cache trails enablement", "error", err)
	}
}

func refreshTrailsEnabledCacheBestEffort(ctx context.Context, client *api.Client) {
	refreshCtx, cancel := context.WithTimeout(ctx, trailEnablementRefreshTimeout)
	defer cancel()
	if _, err := refreshTrailsEnabledCache(refreshCtx, client); err != nil {
		logging.Debug(ctx, "trails enablement refresh skipped", "error", err)
	}
}

func noteTrailCommandEnablement(ctx context.Context, client *api.Client, commandErr error) {
	if commandErr == nil {
		saveTrailsEnabledForRepoBestEffort(ctx, true)
		return
	}
	refreshTrailsEnabledCacheBestEffort(ctx, client)
}

// runAuthenticatedTrailAPI runs fn against the entire-api cell that owns the
// target repository. repoOverride is the raw --repo flag: when non-empty the
// local clone's enablement cache is skipped because the result belongs to a
// different repository.
func runAuthenticatedTrailAPI(ctx context.Context, errW io.Writer, insecureHTTP bool, repoOverride string, fn func(context.Context, *api.Client) error) error {
	_, owner, repo, err := resolveTrailRepoOrRemote(ctx, repoOverride)
	if err != nil {
		return err
	}
	client, err := newTrailAPIClient(ctx, insecureHTTP, owner+"/"+repo)
	if err != nil {
		return renderDataAPIAuthError(errW, err)
	}
	err = fn(ctx, client)
	if repoOverride == "" {
		noteTrailCommandEnablement(ctx, client, err)
	}
	return err
}

