	var value any
	if err := json.Unmarshal([]byte(data), &value); err != nil {
		return fmt.Errorf("decode trail event: %w", err)
	}
	value = normalizeTrailEventValue(value)
	normalized, err := json.Marshal(value)
	if err != nil {
