	}
	if err := json.Unmarshal(normalized, dest); err != nil {
		return fmt.Errorf("decode normalized trail event: %w", err)
	}
	return nil
}

func normalizeTrailEventValue(value any) any {
	switch v := value.(type) {
	case map[string]any:
		out := make(map[string]any, len(v))
		for key, child := range v {
			if key == "payload" {
				out[key] = child
